Here's a C# program that removes all occurrences of a specified item from an array:

```csharp
using System;

class Program
{
    static void Main()
    {
        int[] arr = { 1, 2, 3, 4, 5, 2, 3, 4 };
        int itemToRemove = 2;

        int[] result = RemoveAllOccurrences(arr, itemToRemove);

        Console.WriteLine("Original array:");
        PrintArray(arr);

        Console.WriteLine("\nArray after removing " + itemToRemove + ":");
        PrintArray(result);
    }

    static int[] RemoveAllOccurrences(int[] array, int item)
    {
        if (array == null || array.Length == 0)
            return new int[0];

        int count = 0;

        // Count the number of occurrences
        for (int i = 0; i < array.Length; i++)
        {
            if (array[i] == item)
                count++;
        }

        // Create a new array with the desired size
        int[] newArray = new int[count];
        int index = 0;

        // Fill the new array with non-matching elements
        for (int i = 0; i < array.Length; i++)
        {
            if (array[i] != item)
            {
                newArray[index++] = array[i];
            }
        }

        return newArray;
    }

    static void PrintArray(int[] array)
    {
        Console.WriteLine(string.Join(", ", array));
    }
}
```

